class LiveConfig
{
    private Dictionary<string, string> _current = new();

    public void Reload(Dictionary<string, string> next)
    {
        var copy = new Dictionary<string, string>(next); // never alias the caller's dictionary
        Interlocked.Exchange(ref _current, copy);        // publish the whole version at once
    }

    public string? Get(string key)
    {
        var snapshot = Volatile.Read(ref _current);      // one read: one consistent version
        return snapshot.TryGetValue(key, out var value) ? value : null;
    }
}

