using System.Collections.Concurrent;
using static Bootcamp.Check;

// WorkLog is implemented in the types section at the bottom of the file.

// ──────────────────────────── tests ──────────────────────────────────────

Test("single-threaded pushes drain in FIFO order", () =>
{
    var w = new WorkLog();
    w.Push(1);
    w.Push(2);
    w.Push(3);
    Eq(w.DrainAll(), new[] { 1, 2, 3 });
});

Test("draining an empty log -> [] (boundary)", () =>
    Eq(new WorkLog().DrainAll(), Array.Empty<int>()));

Test("10 000 parallel pushes drain completely: count, sum, distinct", () =>
{
    var w = new WorkLog();
    Parallel.For(0, 10_000, i => w.Push(i));
    var d = w.DrainAll();
    Eq(d.Count, 10000);
    Eq(d.Sum(), 49995000);
    Eq(d.Distinct().Count(), 10000);
