    w.Push(7);
    w.DrainAll();
    Eq(w.DrainAll(), Array.Empty<int>());
});

// ──────────────────────────── types ──────────────────────────────────────

class WorkLog
{
    private readonly ConcurrentQueue<int> _queue = new();

    public void Push(int id) => _queue.Enqueue(id);

    public List<int> DrainAll()
    {
        var drained = new List<int>();
        while (_queue.TryDequeue(out var id))
            drained.Add(id);
        return drained;
    }
}
